const crypto = require('crypto');
const item = $input.first().json || {};
const body = item.body || {};
const query = item.query || {};
const companyId = Number(query.company_id || 0);
const connectionKey = String(query.connection_key || '').trim();
let registry = {};
try { registry = JSON.parse($env.XVOND_MAILGUN_EMAIL_ROUTES_JSON || '{}'); }
catch (_error) { return [{json:{_dispatch:'reject',_response:{success:false},_http_status:403}}]; }
const routeKey = `${companyId}:${connectionKey}`;
const route = registry[routeKey];
if (!companyId || !connectionKey || !route) {
  return [{json:{_dispatch:'reject',_response:{success:false},_http_status:403}}];
}
const signingKey = String(route.webhook_signing_key || '');
const timestamp = String(body.timestamp || '').trim();
const token = String(body.token || '').trim();
const signature = String(body.signature || '').trim().toLowerCase();
const requestTime = Number(timestamp || 0);
const now = Math.floor(Date.now()/1000);
if (signingKey.length < 16 || !requestTime || Math.abs(now-requestTime) > 900 || !token || !signature) {
  return [{json:{_dispatch:'reject',_response:{success:false},_http_status:403}}];
}
const expected = crypto.createHmac('sha256', signingKey).update(timestamp + token).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a,b)) {
  return [{json:{_dispatch:'reject',_response:{success:false},_http_status:403}}];
}
const sender = String(body.sender || body.from || '').trim().slice(0, 200);
const recipient = String(body.recipient || '').trim();
const subject = String(body.subject || '').trim().slice(0, 500);
const plain = String(body['body-plain'] || body['stripped-text'] || '').trim();
const messageId = String(body['Message-Id'] || body['message-id'] || token).trim().slice(0, 180);
if (route.recipient && String(route.recipient).toLowerCase() !== recipient.toLowerCase()) {
  return [{json:{_dispatch:'ignore',_response:{success:true},_http_status:200}}];
}
if (!sender || !recipient || !plain || !messageId) {
  return [{json:{_dispatch:'ignore',_response:{success:true},_http_status:200}}];
}
const message = (subject ? `Subject: ${subject}\n\n${plain}` : plain).slice(0, 12000);
return [{json:{
  _dispatch:'xvond',
  _response:{success:true},
  _http_status:200,
  payload:{
    company_id:Number(route.company_id || companyId),
    agent_id:Number(route.agent_id || 0),
    channel_id:Number(route.channel_id || 0),
    channel_type:'email',
    external_contact_id:sender,
    external_message_id:messageId,
    message
  }
}}];

const item = $input.first().json || {};
const headers = item.headers || {};
const body = item.body || item;
const supplied = String(headers['x-xvond-channel-secret'] || headers['X-Xvond-Channel-Secret'] || '');
const requestId = String(body.request_id || headers['x-xvond-request-id'] || '').trim();
const action = String(body.action || '').trim();
const data = body.data && typeof body.data === 'object' ? body.data : {};
const companyId = Number(body.company_id || 0);
const connectionKey = String(data.connection_key || '').trim();
let registry = {};
try { registry = JSON.parse($env.XVOND_MAILGUN_EMAIL_ROUTES_JSON || '{}'); }
catch (_error) { return [{json:{success:false,request_id:requestId,action,error:'Mailgun email registry is invalid',error_code:'provider_not_configured',data:null}}]; }
const route = registry[`${companyId}:${connectionKey}`];
if (!route || !route.api_key || !route.domain || !route.provider_secret) {
  return [{json:{success:false,request_id:requestId,action,error:'Mailgun email route is not configured',error_code:'provider_not_configured',data:null}}];
}
if (!supplied || supplied !== String(route.provider_secret)) {
  return [{json:{success:false,request_id:requestId,action,error:'Unauthorized Mailgun email provider request',error_code:'unauthorized',data:null}}];
}
if (action !== 'channel.send') {
  return [{json:{success:false,request_id:requestId,action,error:'Unsupported Mailgun email provider action',error_code:'unsupported_action',data:null}}];
}
const to = String(data.external_contact_id || '').trim();
const message = String(data.message || '').trim();
const idempotencyKey = String(data.idempotency_key || '').trim();
const domain = String(route.domain || '').trim();
const fromAddress = String(route.from_address || route.recipient || '').trim();
const defaultSubject = String(route.default_subject || 'Xvond AI Employee').trim();
if (!requestId || !to || !message || !idempotencyKey || !domain || !fromAddress) {
  return [{json:{success:false,request_id:requestId,action,error:'Invalid Mailgun email send contract',error_code:'invalid_contract',data:null}}];
}
const form = new URLSearchParams();
form.set('from', fromAddress);
form.set('to', to);
form.set('subject', defaultSubject);
form.set('text', message);
form.set('v:xvond_idempotency_key', idempotencyKey);
const basic = Buffer.from('api:' + String(route.api_key)).toString('base64');
const region = String(route.region || 'us').trim().toLowerCase();
const apiHost = region === 'eu' ? 'https://api.eu.mailgun.net' : 'https://api.mailgun.net';
const url = apiHost + '/v3/' + encodeURIComponent(domain) + '/messages';
try {
  const response = await fetch(url,{
    method:'POST',
    headers:{'Authorization':'Basic '+basic,'Content-Type':'application/x-www-form-urlencoded','X-Xvond-Request-ID':requestId},
    body:form.toString()
  });
  const payload = await response.json().catch(()=>null);
  const providerId = String(payload?.id || '').trim();
  if (!response.ok || !providerId) {
    return [{json:{success:false,request_id:requestId,action,error:'Mailgun email send was rejected',error_code:'provider_rejected',data:null}}];
  }
  return [{json:{success:true,request_id:requestId,action,data:{provider_message_id:providerId},error:null}}];
} catch (_error) { throw _error; }
